+      const statusRegion = document.getElementById('signup-status');
+
+      const fields = [
+        {
+          input: nameInput,
+          errorEl: document.getElementById('name-error'),
+          getError(el) {
+            if (el.validity.valueMissing) return 'Please enter your full name.';
+            return '';
+          }
+        },
+        {
+          input: emailInput,
+          errorEl: document.getElementById('email-error'),
+          getError(el) {
+            if (el.validity.valueMissing) return 'Please enter your email address.';
+            if (el.validity.typeMismatch) return 'Please enter a valid email address (for example, name@example.com).';
+            return '';
+          }
+        },
+        {
+          input: passwordInput,
+          errorEl: document.getElementById('password-error'),
+          getError(el) {
+            if (el.validity.valueMissing) return 'Please create a password.';
+            if (el.validity.tooShort) return 'Password must be at least 8 characters long.';
+            return '';
+          }
+        }
+      ];
+
