+        passwordInput.type = isShowing ? 'password' : 'text';
+        toggleBtn.setAttribute('aria-pressed', String(!isShowing));
+        toggleBtn.setAttribute('aria-label', isShowing ? 'Show password' : 'Hide password');
+        toggleBtn.textContent = isShowing ? 'Show password' : 'Hide password';
+      });
+
+      function showFieldError(field) {
+        field.input.setCustomValidity('');
+        const msg = field.getError(field.input);
+        if (msg) {
+          field.input.setCustomValidity(msg);
+          field.input.setAttribute('aria-invalid', 'true');
+          field.errorEl.textContent = `Error: ${msg}`;
+          field.errorEl.hidden = false;
+          return false;
+        }
+        clearFieldError(field);
+        return true;
+      }
+
+      function clearFieldError(field) {
+        field.input.setCustomValidity('');
+        field.input.removeAttribute('aria-invalid');
+        field.errorEl.textContent = '';
+        field.errorEl.hidden = true;
+      }
+
+      fields.forEach((field) => {
+        let dirty = false;
+
+        field.input.addEventListener('input', () => {
+          dirty = true;
+          if (!field.errorEl.hidden) {
+            field.input.setCustomValidity('');
+            if (!field.getError(field.input)) {
+              clearFieldError(field);
+            }
+          }
+        });
+
+        field.input.addEventListener('blur', () => {
+          if (dirty) {
