+
+      const dateInput = document.getElementById('dateInput');
+      const timeInput = document.getElementById('timeInput');
+      const hostTzSelect = document.getElementById('hostTzSelect');
+      const grid = document.getElementById('grid');
+      const errorBanner = document.getElementById('errorBanner');
+      const hostSummary = document.getElementById('hostSummary');
+      const utcInstantDisplay = document.getElementById('utcInstantDisplay');
+
+      // Ensure all browser-supported IANA timezones are selectable in #hostTzSelect
+      if (typeof Intl !== 'undefined' && typeof Intl.supportedValuesOf === 'function') {
+        try {
+          const existing = new Set(Array.from(hostTzSelect.options).map(o => o.value));
+          const allTimeZones = Intl.supportedValuesOf('timeZone');
+          const frag = document.createDocumentFragment();
+          for (let i = 0; i < allTimeZones.length; i++) {
+            const tz = allTimeZones[i];
+            if (!existing.has(tz)) {
+              const opt = document.createElement('option');
+              opt.value = tz;
+              opt.textContent = tz;
+              frag.appendChild(opt);
