+  spheres[2].c = Vec(.75, .75, .75);      // Back wall
+  spheres[3].c = Vec(0.0, 0.0, 0.0);      // Front wall (behind camera)
+  spheres[4].c = Vec(.75, .75, .75);      // Bottom floor
+  spheres[5].c = Vec(.75, .75, .75);      // Top ceiling
+  spheres[6].c = Vec(1, 1, 1) * .999;     // Mirror sphere
+  spheres[7].c = Vec(1, 1, 1) * .999;     // Glass sphere
+  spheres[8].c = Vec(0.0, 0.0, 0.0);      // Light sphere (emissive)
