+    for (unsigned short x=0; x<w; x++) {         // Loop cols
+      unsigned short Xi[3] = {
+        (unsigned short)(x + seed_offset),
+        (unsigned short)(y * 31 + seed_offset * 17),
+        (unsigned short)(y * y * y + seed_offset * 131)
+      };
