+__attribute__((export_name("accumulate_pass")))
+void accumulate_pass(int w, int h, int pass_index, int samps, unsigned int seed_offset) {
+  if (w < 1) w = 1;
+  if (h < 1) h = 1;
+  if (w > MAX_W) w = MAX_W;
+  if (h > MAX_H) h = MAX_H;
+  if (samps < 1) samps = 1;
+  if (pass_index < 1) pass_index = 1;
+
