+    (function () {
+      const themeToggle = document.getElementById('theme-toggle');
+      const root = document.documentElement;
+      const body = document.body;
+      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
+
+      function getEffectiveTheme() {
+        const explicitTheme = root.getAttribute('data-theme') || body.getAttribute('data-theme');
+        if (explicitTheme === 'dark' || explicitTheme === 'light') {
+          return explicitTheme;
+        }
+        if (root.classList.contains('dark-mode') || body.classList.contains('dark-mode')) {
+          return 'dark';
+        }
+        if (root.classList.contains('light-mode') || body.classList.contains('light-mode')) {
+          return 'light';
+        }
+        return mediaQuery.matches ? 'dark' : 'light';
+      }
+
+      function updateToggleButton(theme) {
+        if (!themeToggle) return;
+        const isDark = theme === 'dark';
+        themeToggle.setAttribute('aria-pressed', String(isDark));
+        themeToggle.textContent = isDark ? '☀️ Light Mode' : '🌙 Dark Mode';
+      }
+
+      function applyTheme(theme) {
+        const isDark = theme === 'dark';
+        root.setAttribute('data-theme', theme);
+        body.setAttribute('data-theme', theme);
+        root.classList.toggle('dark-mode', isDark);
+        root.classList.toggle('light-mode', !isDark);
+        root.classList.toggle('dark', isDark);
+        root.classList.toggle('light', !isDark);
+        body.classList.toggle('dark-mode', isDark);
+        body.classList.toggle('light-mode', !isDark);
+        body.classList.toggle('dark', isDark);
+        body.classList.toggle('light', !isDark);
+        updateToggleButton(theme);
+        try {
+          localStorage.setItem('theme', theme);
+        } catch (e) {}
+      }
+
+      let savedTheme = null;
+      try {
+        savedTheme = localStorage.getItem('theme');
+      } catch (e) {}
+
+      if (savedTheme === 'dark' || savedTheme === 'light') {
+        applyTheme(savedTheme);
+      } else {
+        updateToggleButton(getEffectiveTheme());
+      }
+
+      if (themeToggle) {
+        themeToggle.addEventListener('click', function () {
+          const nextTheme = getEffectiveTheme() === 'dark' ? 'light' : 'dark';
+          applyTheme(nextTheme);
+        });
+      }
+
+      if (mediaQuery.addEventListener) {
+        mediaQuery.addEventListener('change', function () {
