@@ -0,0 +1,74 @@
+import http from 'node:http';
+import fs from 'node:fs';
+import path from 'node:path';
+import os from 'node:os';
+
+const args = process.argv.slice(2);
+let portArg = process.env.PORT || 11222;
+for (let i = 0; i < args.length; i++) {
+  if (args[i] === '--port' && args[i + 1]) {
+    portArg = Number(args[i + 1]);
+  }
+}
+const PORT = Number(portArg) || 11222;
+const ROOT = process.cwd();
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.mjs': 'application/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.webmanifest': 'application/manifest+json; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.svg': 'image/svg+xml',
+  '.png': 'image/png',
+  '.ico': 'image/x-icon'
+};
+
+const server = http.createServer((req, res) => {
+  const reqUrl = new URL(req.url || '/', `http://localhost:${PORT}`);
+  let pathname = decodeURIComponent(reqUrl.pathname);
+
+  res.setHeader('Access-Control-Allow-Origin', '*');
+
+  let filePath = path.join(ROOT, pathname);
+  if (!filePath.startsWith(ROOT)) {
+    res.writeHead(403);
+    res.end('Forbidden');
+    return;
+  }
+
+  try {
+    if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
+      filePath = path.join(filePath, 'index.html');
+    } else if (!fs.existsSync(filePath) && fs.existsSync(filePath + '.html')) {
+      filePath = filePath + '.html';
+    }
+
+    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
+      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Not Found');
+      return;
+    }
+
+    let contentType = MIME_TYPES[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
+    if (pathname.includes('.well-known/web-app-origin-association')) {
+      contentType = 'application/json; charset=utf-8';
+    } else if (pathname.endsWith('/manifest.json')) {
+      contentType = 'application/manifest+json; charset=utf-8';
+    }
+
+    const content = fs.readFileSync(filePath);
+    res.writeHead(200, { 'Content-Type': contentType });
+    res.end(content);
+  } catch (err) {
+    res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Internal Server Error');
+  }
+});
+
+server.listen(PORT, 'localhost', () => {
+  const url = `http://localhost:${PORT}`;
+  const formattedPath = ROOT.replace(os.homedir(), '~');
+  console.log(`\x1b[1m\x1b[37m 🤓 ${url} \x1b[0m statikk serving locally: \x1b[2m\x1b[37m${formattedPath}\x1b[0m`);
+});
