+import aaguids from './aaguids.json' with { type: 'json' };
+
+// Predefined server RP ID constant (must match registration rp.id; never derived from window.location.hostname)
+export const RP_ID = 'localhost';
+export const RP_NAME = 'The Daily Grind Coffee Co.';
+
+const STORAGE_KEY_CREDENTIALS = 'daily_grind_passkey_credentials_v1';
+const STORAGE_KEY_USER = 'daily_grind_user_profile_v1';
+
+const DEFAULT_USER = {
+  id: 'user-daily-grind-01',
+  // Valid unpadded Base64URL string (Buffer.from('user-daily-grind-01').toString('base64url'))
+  passkeyUserId: 'dXNlci1kYWlseS1ncmluZC0wMQ',
+  name: 'alex.rivera@dailygrind.coffee',
+  displayName: 'Alex Rivera',
+};
+
+export function lookupAaguidMetadata(aaguid) {
+  if (!aaguid || aaguid === '00000000-0000-0000-0000-000000000000') {
+    return {
+      aaguid: '00000000-0000-0000-0000-000000000000',
+      name: 'Unknown passkey provider',
+      providerIcon: undefined,
+      iconDark: undefined,
+    };
+  }
+  const provider = aaguids[aaguid];
+  return {
+    aaguid,
+    name: provider?.name || 'Unknown passkey provider',
+    providerIcon: provider?.icon_light,
+    iconDark: provider?.icon_dark,
+  };
+}
+
+function createInitialCredentials() {
+  const googleMeta = lookupAaguidMetadata('ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4');
+  const icloudMeta = lookupAaguidMetadata('fbfc3007-154e-4ecc-8c0b-6e020557d7bd');
+  const yubikeyMeta = lookupAaguidMetadata('2fc0579f-8113-47ea-b116-bb5a8db9202a');
+
+  return [
+    {
+      // Valid unpadded Base64URL string (Buffer.from('cred-google-passkey-01').toString('base64url'))
+      id: 'Y3JlZC1nb29nbGUtcGFzc2tleS0wMQ',
+      passkeyUserId: DEFAULT_USER.passkeyUserId,
+      credentialPublicKey: 'pQECAyYgASFYIJV8dXNlci1wdWJsaWMta2V5LTAxIlggY3JlZC1wdWJsaWMta2V5LTAx',
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: googleMeta.aaguid,
+      providerIcon: googleMeta.providerIcon,
+      name: googleMeta.name,
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1758463200000,
+      lastUsedAt: 1762689600000,
+      counter: 14,
+    },
+    {
+      // Valid unpadded Base64URL string (Buffer.from('cred-icloud-passkey-02').toString('base64url'))
+      id: 'Y3JlZC1pY2xvdWQtcGFzc2tleS0wMg',
+      passkeyUserId: DEFAULT_USER.passkeyUserId,
+      credentialPublicKey: 'pQECAyYgASFYIJV8dXNlci1wdWJsaWMta2V5LTAyIlggY3JlZC1wdWJsaWMta2V5LTAy',
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: icloudMeta.aaguid,
+      providerIcon: icloudMeta.providerIcon,
+      name: 'MacBook Pro — iCloud Keychain',
+      transports: ['internal', 'hybrid'],
+      registeredAt: 1755871200000,
+      lastUsedAt: 1762171200000,
+      counter: 8,
+    },
+    {
+      // Valid unpadded Base64URL string (Buffer.from('cred-yubikey-passkey-03').toString('base64url'))
+      id: 'Y3JlZC15dWJpa2V5LXBhc3NrZXktMDM',
+      passkeyUserId: DEFAULT_USER.passkeyUserId,
+      credentialPublicKey: 'pQECAyYgASFYIJV8dXNlci1wdWJsaWMta2V5LTAzIlggY3JlZC1wdWJsaWMta2V5LTAz',
+      credentialType: 'public-key',
+      credentialDeviceType: 'singleDevice',
+      credentialBackedUp: false,
+      aaguid: yubikeyMeta.aaguid,
+      providerIcon: yubikeyMeta.providerIcon,
+      name: yubikeyMeta.name,
+      transports: ['usb', 'nfc'],
+      registeredAt: 1750600800000,
+      lastUsedAt: 1759413600000,
+      counter: 3,
+    },
+  ];
+}
+
+function loadUserFromStore() {
+  try {
+    const raw = localStorage.getItem(STORAGE_KEY_USER);
+    if (raw) {
+      const parsed = JSON.parse(raw);
+      if (parsed && parsed.passkeyUserId) return parsed;
+    }
+  } catch {
+    // Fallback to default in restricted storage contexts
+  }
+  return { ...DEFAULT_USER };
+}
+
+function saveUserToStore(user) {
+  try {
+    localStorage.setItem(STORAGE_KEY_USER, JSON.stringify(user));
+  } catch {
+    // Ignore storage errors
+  }
+}
+
+function loadCredentialsFromStore() {
+  try {
+    const raw = localStorage.getItem(STORAGE_KEY_CREDENTIALS);
+    if (raw) {
+      const parsed = JSON.parse(raw);
+      if (Array.isArray(parsed)) return parsed;
+    }
+  } catch {
+    // Fallback to initial credentials
+  }
+  const initial = createInitialCredentials();
+  saveCredentialsToStore(initial);
+  return initial;
+}
+
+function saveCredentialsToStore(credentials) {
+  try {
+    localStorage.setItem(STORAGE_KEY_CREDENTIALS, JSON.stringify(credentials));
+  } catch {
+    // Ignore storage errors
+  }
+}
+
+function generateBase64UrlChallenge(byteLength = 32) {
+  const bytes = new Uint8Array(byteLength);
+  if (globalThis.crypto && globalThis.crypto.getRandomValues) {
+    globalThis.crypto.getRandomValues(bytes);
+  } else {
+    for (let i = 0; i < byteLength; i++) {
+      bytes[i] = (i * 37 + 11) & 0xff;
+    }
+  }
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+function jsonResponse(body, status = 200) {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json' },
+  });
+}
+
+async function handleMockApiRequest(urlString, init = {}) {
+  const url = new URL(urlString, 'http://localhost');
+  const pathname = url.pathname;
+  const method = (init.method || 'GET').toUpperCase();
+  const bodyText = typeof init.body === 'string' ? init.body : '';
+  const body = bodyText ? JSON.parse(bodyText) : {};
+
+  if (pathname === '/api/credentials' && method === 'GET') {
+    const user = loadUserFromStore();
+    const credentials = loadCredentialsFromStore();
+    return jsonResponse({
+      rpId: RP_ID,
+      userId: user.passkeyUserId,
+      user,
+      credentials,
+    });
+  }
+
+  if (pathname.startsWith('/api/credential/') && method === 'PUT') {
+    const id = decodeURIComponent(pathname.slice('/api/credential/'.length));
+    const credentials = loadCredentialsFromStore();
+    const cred = credentials.find((c) => c.id === id);
+    if (!cred) {
+      return jsonResponse({ error: 'Credential not found.' }, 404);
+    }
+    const trimmedName = typeof body.name === 'string' ? body.name.trim() : '';
+    if (!trimmedName) {
+      return jsonResponse({ error: 'Credential name is required.' }, 400);
+    }
+    cred.name = trimmedName;
+    saveCredentialsToStore(credentials);
+    return jsonResponse(cred);
+  }
+
+  if (pathname.startsWith('/api/credential/') && method === 'DELETE') {
+    const id = decodeURIComponent(pathname.slice('/api/credential/'.length));
+    const credentials = loadCredentialsFromStore();
+    const index = credentials.findIndex((c) => c.id === id);
+    if (index === -1) {
+      return jsonResponse({ error: 'Credential not found.' }, 404);
+    }
+    credentials.splice(index, 1);
+    saveCredentialsToStore(credentials);
+    return jsonResponse({ success: true });
+  }
+
+  if (pathname === '/api/user' && method === 'PUT') {
+    const user = loadUserFromStore();
+    const updatedUser = {
+      ...user,
+      name: typeof body.name === 'string' && body.name.trim() ? body.name.trim() : user.name,
+      displayName:
+        typeof body.displayName === 'string' && body.displayName.trim()
+          ? body.displayName.trim()
+          : user.displayName,
+    };
+    saveUserToStore(updatedUser);
+    return jsonResponse({
+      ...updatedUser,
+      rpId: RP_ID,
+      userId: updatedUser.passkeyUserId,
+    });
+  }
+
+  if (pathname === '/api/register/options' && method === 'POST') {
+    const isPromotionFlow = Boolean(body.promotion);
+    const user = loadUserFromStore();
+    const userExistingCredentials = loadCredentialsFromStore();
+    const options = {
+      challenge: generateBase64UrlChallenge(32),
+      rp: { id: RP_ID, name: RP_NAME },
+      user: {
+        id: user.passkeyUserId,
+        name: user.name,
+        displayName: user.displayName,
+      },
+      pubKeyCredParams: [
+        { type: 'public-key', alg: -7 },
+        { type: 'public-key', alg: -257 },
+      ],
+      excludeCredentials: userExistingCredentials.map((cred) => ({
+        type: 'public-key',
+        id: cred.id,
+        transports: cred.transports,
+      })),
+      authenticatorSelection: {
+        residentKey: 'required',
+        requireResidentKey: true,
+        userVerification: 'preferred',
+        ...(isPromotionFlow && { authenticatorAttachment: 'platform' }),
+      },
+    };
+    return jsonResponse(options);
+  }
+
+  if (pathname === '/api/register/verify' && method === 'POST') {
+    const user = loadUserFromStore();
+    const credentials = loadCredentialsFromStore();
+    const aaguid = body.aaguid || 'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4';
+    const meta = lookupAaguidMetadata(aaguid);
+    const now = Date.now();
+    const newCredential = {
+      id: body.id || generateBase64UrlChallenge(24),
+      passkeyUserId: user.passkeyUserId,
+      credentialPublicKey:
+        body.response?.attestationObject ||
+        'pQECAyYgASFYIJV8dXNlci1wdWJsaWMta2V5LW5ldyJYIG5ldy1jcmVkLXB1YmxpYy1rZXk',
+      credentialType: 'public-key',
+      credentialDeviceType: 'multiDevice',
+      credentialBackedUp: true,
+      aaguid: meta.aaguid,
+      providerIcon: meta.providerIcon,
+      name: meta.name,
+      transports: body.response?.transports || ['internal', 'hybrid'],
+      registeredAt: now,
+      lastUsedAt: now,
+      counter: 0,
+    };
+    credentials.unshift(newCredential);
+    saveCredentialsToStore(credentials);
+    return jsonResponse({ verified: true, credential: newCredential });
+  }
+
+  return null;
+}
+
+// Install local API handler on window.fetch so static hosting handles /api/* without 404 console errors
+if (typeof window !== 'undefined' && typeof window.fetch === 'function') {
+  const nativeFetch = window.fetch.bind(window);
+  window.fetch = async function dailyGrindFetch(input, init) {
+    const urlString = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
+    if (urlString && (urlString.startsWith('/api/') || urlString.includes('/api/'))) {
+      const mockRes = await handleMockApiRequest(urlString, init);
+      if (mockRes) return mockRes;
+    }
+    return nativeFetch(input, init);
+  };
+}
+
+export async function listFetch() {
+  return window.fetch('/api/credentials', {
+    method: 'GET',
+    headers: { Accept: 'application/json' },
+  });
+}
+
+export async function renameCredentialFetch(credentialId, { name }) {
+  return window.fetch(`/api/credential/${encodeURIComponent(credentialId)}`, {
+    method: 'PUT',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ name }),
+  });
+}
+
+export async function deleteFetch(credentialId) {
+  return window.fetch(`/api/credential/${encodeURIComponent(credentialId)}`, {
+    method: 'DELETE',
+    headers: { Accept: 'application/json' },
+  });
+}
+
+export async function updateUserFetch({ name, displayName }) {
+  return window.fetch('/api/user', {
+    method: 'PUT',
+    headers: { 'Content-Type': 'application/json' },
+    body: JSON.stringify({ name, displayName }),
+  });
+}
+
+export async function optionsFetch({ promotion = false } = {}) {
+  const response = await window.fetch('/api/register/options', {
