+
+export function getProviderDetailsFromAaguid(credential) {
+  const { aaguid } = credential;
+  if (!aaguid || aaguid === '00000000-0000-0000-0000-000000000000') {
+    return {
+      aaguid: '00000000-0000-0000-0000-000000000000',
+      providerName: 'Unknown passkey provider',
+      displayName: credential.name || 'Unknown passkey provider',
+      providerIcon: undefined,
+      iconDark: undefined,
+    };
+  }
+
+  const provider = aaguids[aaguid];
+  const providerName = provider?.name || 'Unknown passkey provider';
+  return {
+    aaguid,
+    providerName,
+    displayName: credential.name || providerName,
+    providerIcon: credential.providerIcon || provider?.icon_light,
+    iconDark: provider?.icon_dark,
+  };
+}
+
+function formatEpochDate(epochMs) {
+  if (!epochMs || typeof epochMs !== 'number') return 'Never';
+  try {
+    return new Date(epochMs).toLocaleDateString('en-US', {
+      year: 'numeric',
+      month: 'short',
+      day: 'numeric',
+    });
+  } catch {
+    return 'Unknown';
+  }
+}
+
+function setStatusBanner(message, type = 'info') {
+  const statusEl = document.getElementById('passkey-status-banner');
+  if (!statusEl) return;
+  if (!message) {
+    statusEl.hidden = true;
+    statusEl.textContent = '';
+    statusEl.className = 'status-banner';
+    return;
+  }
+  statusEl.textContent = message;
+  statusEl.className = `status-banner status-${type}`;
+  statusEl.hidden = false;
+}
+
+function showStandardPasswordFallbackUI() {
+  const createButton = document.getElementById('create-passkey');
+  const fallbackNotice = document.getElementById('mfa-fallback-notice');
+  if (createButton) {
+    createButton.hidden = true;
+    createButton.disabled = true;
+  }
+  if (fallbackNotice) {
+    fallbackNotice.hidden = false;
+  }
+}
+
+export async function isPasskeySupported() {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) {
+    return false;
+  }
+  try {
+    const capabilities = await PublicKeyCredential.getClientCapabilities();
+    return Boolean(capabilities.passkeyPlatformAuthenticator);
+  } catch {
+    return false;
+  }
+}
+
+export async function syncAcceptedCredentials(rpId, userId, currentCredentialsList) {
+  if (!window.PublicKeyCredential || !PublicKeyCredential.signalAllAcceptedCredentials) return;
+  const credentialIds = currentCredentialsList.map((c) => c.id);
+  if (!rpId || !isValidBase64Url(userId) || !credentialIds.every(isValidBase64Url)) {
+    console.warn(
+      'SignalAllAcceptedCredentials skipped: server rpId and valid unpadded Base64URL userId and credential IDs are required.'
+    );
+    return;
+  }
+
+  try {
+    await PublicKeyCredential.signalAllAcceptedCredentials({
+      rpId,
+      userId,
+      allAcceptedCredentialIds: credentialIds,
+    });
+  } catch (e) {
+    console.warn('SignalAllAcceptedCredentials sync warning:', e);
+  }
+}
+
+export function renderUI(credentials = []) {
+  const listContainer = document.getElementById('passkey-list');
+  const emptyState = document.getElementById('passkey-empty-state');
+  const countBadge = document.getElementById('passkey-count-badge');
+
+  if (countBadge) {
+    countBadge.textContent = `${credentials.length} ${credentials.length === 1 ? 'key' : 'keys'}`;
+  }
+
+  if (!listContainer) return;
+  listContainer.replaceChildren();
+
+  if (!Array.isArray(credentials) || credentials.length === 0) {
+    listContainer.hidden = true;
+    if (emptyState) emptyState.hidden = false;
+    return;
+  }
+
+  listContainer.hidden = false;
+  if (emptyState) emptyState.hidden = true;
+
+  for (const cred of credentials) {
+    const details = getProviderDetailsFromAaguid(cred);
+    const item = document.createElement('li');
+    item.className = 'passkey-row';
+    item.dataset.credentialId = cred.id;
+
+    const mainRow = document.createElement('div');
+    mainRow.className = 'passkey-row-main';
+
+    // Provider Icon
+    const iconWrapper = document.createElement('div');
+    iconWrapper.className = 'passkey-icon-wrapper';
+    const img = document.createElement('img');
+    img.className = 'passkey-provider-icon';
+    img.src = details.providerIcon || FALLBACK_KEY_ICON;
+    img.alt = `${details.providerName} icon`;
+    img.width = 36;
+    img.height = 36;
+    iconWrapper.appendChild(img);
+
+    // Info Column
+    const infoCol = document.createElement('div');
+    infoCol.className = 'passkey-info';
+
+    const titleRow = document.createElement('div');
+    titleRow.className = 'passkey-title-row';
+
+    const nameEl = document.createElement('span');
+    nameEl.className = 'passkey-name';
+    nameEl.textContent = details.displayName;
+    titleRow.appendChild(nameEl);
+
+    const syncBadge = document.createElement('span');
+    syncBadge.className = cred.credentialBackedUp
+      ? 'passkey-badge badge-synced'
+      : 'passkey-badge badge-device';
+    syncBadge.textContent = cred.credentialBackedUp ? 'Synced' : 'Hardware / Device-bound';
+    titleRow.appendChild(syncBadge);
+
+    if (details.displayName !== details.providerName) {
+      const providerSub = document.createElement('span');
+      providerSub.className = 'passkey-provider-subtitle';
+      providerSub.textContent = details.providerName;
+      titleRow.appendChild(providerSub);
+    }
+
+    const metaRow = document.createElement('div');
+    metaRow.className = 'passkey-meta-row';
+
+    const regSpan = document.createElement('span');
+    regSpan.className = 'passkey-date passkey-registered-at';
+    regSpan.textContent = `Registered: ${formatEpochDate(cred.registeredAt)}`;
+    metaRow.appendChild(regSpan);
+
+    const lastUsedSpan = document.createElement('span');
+    lastUsedSpan.className = 'passkey-date passkey-last-used-at';
+    lastUsedSpan.textContent = `Last used: ${formatEpochDate(cred.lastUsedAt)}`;
+    metaRow.appendChild(lastUsedSpan);
+
+    infoCol.append(titleRow, metaRow);
+
+    // Action Buttons
+    const actionsCol = document.createElement('div');
+    actionsCol.className = 'passkey-actions';
+
+    const renameBtn = document.createElement('button');
+    renameBtn.type = 'button';
+    renameBtn.className = 'btn-secondary btn-rename';
+    renameBtn.dataset.id = cred.id;
+    renameBtn.setAttribute('aria-label', `Rename ${details.displayName}`);
+    renameBtn.textContent = 'Rename';
+
+    const deleteBtn = document.createElement('button');
+    deleteBtn.type = 'button';
+    deleteBtn.className = 'btn-danger btn-delete';
+    deleteBtn.dataset.id = cred.id;
+    deleteBtn.setAttribute('aria-label', `Delete ${details.displayName}`);
+    deleteBtn.textContent = 'Delete';
+
+    actionsCol.append(renameBtn, deleteBtn);
+    mainRow.append(iconWrapper, infoCol, actionsCol);
+
+    // Inline Rename Form
+    const renameForm = document.createElement('form');
+    renameForm.className = 'passkey-rename-form';
+    renameForm.hidden = true;
+
+    const renameLabel = document.createElement('label');
+    renameLabel.className = 'sr-only';
+    const inputId = `rename-input-${cred.id}`;
+    renameLabel.htmlFor = inputId;
+    renameLabel.textContent = `New nickname for ${details.displayName}`;
+
+    const renameInput = document.createElement('input');
+    renameInput.type = 'text';
+    renameInput.id = inputId;
+    renameInput.name = 'name';
+    renameInput.className = 'passkey-rename-input';
+    renameInput.value = details.displayName;
+    renameInput.required = true;
+    renameInput.maxLength = 80;
+
+    const saveRenameBtn = document.createElement('button');
+    saveRenameBtn.type = 'submit';
+    saveRenameBtn.className = 'btn btn-small btn-save-rename';
+    saveRenameBtn.textContent = 'Save';
+
+    const cancelRenameBtn = document.createElement('button');
+    cancelRenameBtn.type = 'button';
+    cancelRenameBtn.className = 'btn-secondary btn-small btn-cancel-rename';
+    cancelRenameBtn.textContent = 'Cancel';
+
+    renameForm.append(renameLabel, renameInput, saveRenameBtn, cancelRenameBtn);
+
+    renameBtn.addEventListener('click', () => {
+      const isCurrentlyHidden = renameForm.hidden;
+      renameForm.hidden = !isCurrentlyHidden;
+      if (!renameForm.hidden) {
+        renameInput.value = details.displayName;
+        renameInput.focus();
+        renameInput.select();
+      }
+    });
+
+    cancelRenameBtn.addEventListener('click', () => {
+      renameForm.hidden = true;
+    });
+
+    renameForm.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      const newName = renameInput.value.trim();
+      if (!newName) return;
+      await performCredentialRename(cred.id, newName);
+    });
+
+    deleteBtn.addEventListener('click', async () => {
+      await performDelete(cred.id);
+    });
+
+    item.append(mainRow, renameForm);
+    listContainer.appendChild(item);
+  }
+}
+
+export async function loadManagementPanel() {
+  const createButton = document.getElementById('create-passkey');
+  const fallbackNotice = document.getElementById('mfa-fallback-notice');
+  const supported = await isPasskeySupported();
+  if (!supported) {
+    if (createButton) {
+      createButton.hidden = true;
+      createButton.disabled = true;
+    }
+    if (fallbackNotice) {
+      fallbackNotice.hidden = false;
+    }
+  } else {
+    if (createButton) {
+      createButton.hidden = false;
+      createButton.disabled = false;
+    }
+    if (fallbackNotice) {
+      fallbackNotice.hidden = true;
+    }
+  }
+
+  const response = await listFetch();
+  const { rpId, userId, user, credentials } = await response.json();
+
+  if (user) {
+    const userNameInput = document.getElementById('user-name-input');
+    const userDisplayNameInput = document.getElementById('user-display-name-input');
+    if (userNameInput && user.name) userNameInput.value = user.name;
+    if (userDisplayNameInput && user.displayName) userDisplayNameInput.value = user.displayName;
+  }
+
+  renderUI(credentials);
+  // Sync accepted credentials on initial load using server-provided rpId and userId
+  await syncAcceptedCredentials(rpId, userId, credentials);
+}
+
+export async function performDelete(credentialId) {
+  const response = await deleteFetch(credentialId);
+  if (response.ok) {
+    const updatedResponse = await listFetch();
+    const { rpId, userId, credentials } = await updatedResponse.json();
+
+    renderUI(credentials);
+    setStatusBanner('Passkey removed and synced with your authenticator.', 'success');
+    // Sync remaining accepted credentials after deletion
+    await syncAcceptedCredentials(rpId, userId, credentials);
+  } else {
+    setStatusBanner('Could not delete passkey. Please try again.', 'error');
+  }
+}
+
+// Renaming a passkey's nickname updates the server record only
+export async function performCredentialRename(credentialId, newCredentialName) {
+  const response = await renameCredentialFetch(credentialId, { name: newCredentialName });
+  if (response.ok) {
+    const updatedResponse = await listFetch();
+    const { credentials } = await updatedResponse.json();
+    renderUI(credentials);
+    setStatusBanner(`Passkey renamed to "${newCredentialName}".`, 'success');
+  } else {
+    setStatusBanner('Could not rename passkey. Please try again.', 'error');
+  }
+}
+
+// Renaming the user's account username or displayName triggers signalCurrentUserDetails
+export async function performUserRename(updatedName, updatedDisplayName) {
+  const response = await updateUserFetch({ name: updatedName, displayName: updatedDisplayName });
+  if (response.ok) {
+    setStatusBanner('Account profile updated and synced with your passkey authenticator.', 'success');
+    if (window.PublicKeyCredential && PublicKeyCredential.signalCurrentUserDetails) {
+      const { rpId, userId } = await response.json();
+      if (!rpId || !isValidBase64Url(userId)) {
+        console.warn(
+          'SignalCurrentUserDetails skipped: server rpId and valid unpadded Base64URL userId are required.'
+        );
+        return;
+      }
+      try {
+        await PublicKeyCredential.signalCurrentUserDetails({
+          rpId,
+          userId,
+          name: updatedName,
+          displayName: updatedDisplayName,
+        });
+      } catch (e) {
+        console.warn('SignalCurrentUserDetails sync warning:', e);
+      }
+    }
+  } else {
+    setStatusBanner('Could not update account details. Please try again.', 'error');
+  }
+}
+
+export async function registerPasskey(isPromotion = false) {
+  const capabilities = await PublicKeyCredential.getClientCapabilities();
+  if (!capabilities.passkeyPlatformAuthenticator || !capabilities.conditionalGet) {
+    showStandardPasswordFallbackUI();
+    return;
+  }
+
+  const creationOptionsJSON = await optionsFetch({ promotion: isPromotion });
+  const publicKey = PublicKeyCredential.parseCreationOptionsFromJSON(creationOptionsJSON);
+
+  let credential;
+  try {
+    credential = await navigator.credentials.create({ publicKey });
+  } catch (err) {
+    if (err.name === 'InvalidStateError') {
+      setStatusBanner('A passkey already exists on this authenticator for your account.', 'info');
+    } else if (err.name === 'SecurityError') {
+      setStatusBanner('Configuration RP ID or Secure Context error.', 'error');
+    } else if (err.name === 'NotAllowedError') {
+      setStatusBanner('Passkey registration was cancelled.', 'info');
+    } else if (err.name === 'AbortError') {
+      setStatusBanner('Passkey creation operation was aborted.', 'info');
+    }
+    return;
+  }
+
+  if (!credential) return;
+
+  const encodedResponse = credential.toJSON();
+  try {
+    const response = await registerVerifyFetch(encodedResponse);
+    if (!response.ok) {
+      if (PublicKeyCredential.signalUnknownCredential) {
+        try {
+          await PublicKeyCredential.signalUnknownCredential({
+            rpId: publicKey.rp.id,
+            credentialId: encodedResponse.id,
+          });
+        } catch (e) {
+          console.warn('SignalUnknownCredential sync warning:', e);
+        }
+      }
+      setStatusBanner('Server could not verify the new passkey.', 'error');
+      return;
+    }
+
+    setStatusBanner('New passkey registered to your account.', 'success');
+    await loadManagementPanel();
+  } catch (serverErr) {
+    console.warn('Server verification network failure:', serverErr);
+    if (PublicKeyCredential.signalUnknownCredential) {
+      try {
+        await PublicKeyCredential.signalUnknownCredential({
+          rpId: publicKey.rp.id,
+          credentialId: encodedResponse.id,
+        });
+      } catch (e) {
+        console.warn('SignalUnknownCredential sync warning:', e);
+      }
+    }
+    setStatusBanner('Network error while verifying passkey registration.', 'error');
+  }
+}
+
+function attachEventListeners() {
+  const createButton = document.getElementById('create-passkey');
+  if (createButton) {
+    createButton.addEventListener('click', () => {
+      registerPasskey(false);
+    });
+  }
+
+  const userProfileForm = document.getElementById('user-profile-form');
+  if (userProfileForm) {
+    userProfileForm.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      const userNameInput = document.getElementById('user-name-input');
+      const userDisplayNameInput = document.getElementById('user-display-name-input');
+      const updatedName = userNameInput ? userNameInput.value.trim() : '';
+      const updatedDisplayName = userDisplayNameInput ? userDisplayNameInput.value.trim() : '';
+      if (!updatedName || !updatedDisplayName) return;
+      await performUserRename(updatedName, updatedDisplayName);
+    });
+  }
+}
+
+function init() {
+  attachEventListeners();
+  loadManagementPanel();
+}
+
+if (document.readyState === 'loading') {
+  window.addEventListener('DOMContentLoaded', init);
+} else {
+  init();
+}
