+    }
+
+    if (cancelAddBtn && addPasskeyForm) {
+      cancelAddBtn.addEventListener('click', () => {
+        addPasskeyForm.hidden = true;
+      });
+    }
+
+    if (addPasskeyForm) {
+      addPasskeyForm.addEventListener('submit', async (e) => {
+        e.preventDefault();
