+          reason: 'Restored default registered passkeys'
+        });
+        showNotification('Default passkeys restored and authenticator synced.', 'success');
+      });
+    }
+  }
+
+  async function initPasskeyManager() {
+    const accountSection = document.getElementById('account');
+    if (!accountSection) return;
+
+    renderProfileSection();
+    renderPasskeysList();
+    bindGlobalControls();
+
+    // Perform initial authenticator sync so browser passkey store matches registered credentials
+    await syncBrowserAuthenticator({
+      reason: 'Initial account passkey sync'
+    });
+  }
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', initPasskeyManager);
+  } else {
+    initPasskeyManager();
+  }
