+                        </div>
+                      ) : (
+                        <div className="flex flex-wrap items-center gap-2">
+                          <h3 className="text-base font-bold text-gray-900">
+                            {passkey.displayName}
+                          </h3>
+                          <span
+                            className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${
+                              passkey.backedUp
+                                ? 'bg-green-100 text-green-800'
+                                : 'bg-amber-100 text-amber-800'
+                            }`}
+                          >
+                            {passkey.backedUp ? 'Synced Passkey' : 'Device-Bound Key'}
+                          </span>
+                          <span className="text-xs text-gray-500">
+                            &bull; {passkey.authenticatorName}
+                          </span>
+                        </div>
+                      )}
+
+                      <div className="mt-1.5 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-gray-500">
+                        <span>
+                          Credential ID:{' '}
+                          <code className="font-mono bg-gray-100 px-1.5 py-0.5 rounded text-gray-700">
+                            {passkey.credentialId}
+                          </code>
+                        </span>
+                        <span>Created: {formatDate(passkey.createdAt)}</span>
+                        <span>Last used: {formatDate(passkey.lastUsedAt)}</span>
+                        <span>
+                          Transports: {passkey.transports.join(', ')}
+                        </span>
+                      </div>
+                    </div>
+                  </div>
+
+                  {/* Passkey Action Buttons */}
+                  <div className="flex items-center space-x-2 self-end md:self-center flex-shrink-0">
+                    {!isEditing && (
+                      <button
+                        type="button"
+                        onClick={() => startEditingPasskey(passkey)}
+                        aria-label={`Edit display name for ${passkey.displayName}`}
+                        className="px-3 py-1.5 border border-gray-300 rounded text-xs font-semibold text-gray-700 hover:bg-gray-50 cursor-pointer"
+                      >
+                        Edit Display Name
+                      </button>
+                    )}
+                    <button
+                      type="button"
+                      disabled={isRemoving}
+                      onClick={() => handleRemovePasskey(passkey)}
+                      aria-label={`Remove passkey ${passkey.displayName}`}
+                      className="px-3 py-1.5 border border-red-300 bg-red-50 rounded text-xs font-semibold text-red-700 hover:bg-red-100 disabled:opacity-60 cursor-pointer"
+                    >
+                      {isRemoving ? 'Removing...' : 'Remove'}
+                    </button>
+                  </div>
+                </li>
+              );
+            })}
+          </ul>
+        )}
+
+        {/* Register a New Passkey Form */}
+        <div className="pt-5 border-t border-gray-200">
+          <h3 className="text-sm font-bold text-gray-900 mb-2">
+            Register a New Passkey on This Device
+          </h3>
+          <form
+            onSubmit={handleRegisterNewPasskey}
+            className="flex flex-col sm:flex-row gap-3"
+          >
+            <label htmlFor="new-passkey-label" className="sr-only">
+              New Passkey Display Name
+            </label>
+            <input
+              id="new-passkey-label"
+              type="text"
+              placeholder="Display name for new passkey (e.g., Work Laptop Chrome)"
+              value={newPasskeyLabel}
+              onChange={(e) => setNewPasskeyLabel(e.target.value)}
+              className="flex-grow px-3 py-2 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-gray-900"
+            />
+            <button
+              type="submit"
+              disabled={registeringPasskey}
+              className="px-4 py-2 bg-gray-900 text-white text-sm font-semibold rounded-md hover:bg-gray-800 whitespace-nowrap disabled:opacity-60 cursor-pointer"
+            >
+              {registeringPasskey ? 'Registering...' : 'Add Passkey'}
+            </button>
+          </form>
+        </div>
+      </section>
+
+      {/* Section 3: Browser Authenticator Synchronization Status (WebAuthn Signal API) */}
+      <section
+        aria-labelledby="authenticator-sync-heading"
+        className="bg-gray-50 border border-gray-200 rounded-lg p-6"
+      >
+        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between pb-4 mb-4 border-b border-gray-200 gap-2">
+          <div>
+            <h2
+              id="authenticator-sync-heading"
+              className="text-base font-bold text-gray-900"
+            >
+              Browser Authenticator Synchronization Log (WebAuthn Signal API)
+            </h2>
+            <p className="text-xs text-gray-600 mt-0.5">
+              Signals sent to your browser&apos;s credential manager to prune removed keys and update display names.
+            </p>
+          </div>
+          <div className="flex flex-wrap gap-1.5 text-xs">
+            <span
+              className={`px-2 py-0.5 rounded font-mono ${
+                signalCapabilities.allAccepted
+                  ? 'bg-green-100 text-green-800'
+                  : 'bg-gray-200 text-gray-700'
+              }`}
+            >
+              signalAllAcceptedCredentials
+            </span>
+            <span
+              className={`px-2 py-0.5 rounded font-mono ${
+                signalCapabilities.unknownCredential
+                  ? 'bg-green-100 text-green-800'
+                  : 'bg-gray-200 text-gray-700'
+              }`}
+            >
+              signalUnknownCredential
+            </span>
+            <span
+              className={`px-2 py-0.5 rounded font-mono ${
+                signalCapabilities.currentUserDetails
+                  ? 'bg-green-100 text-green-800'
+                  : 'bg-gray-200 text-gray-700'
+              }`}
+            >
+              signalCurrentUserDetails
+            </span>
+          </div>
+        </div>
+
+        {syncLogs.length === 0 ? (
+          <p className="text-xs text-gray-500">
+            No authenticator signals dispatched yet in this session.
+          </p>
+        ) : (
+          <ul className="space-y-2.5 text-xs" data-testid="authenticator-sync-log">
+            {syncLogs.map((entry) => (
+              <li
+                key={entry.id}
+                className="bg-white border border-gray-200 rounded p-3"
+              >
+                <div className="flex flex-wrap items-center justify-between gap-2 mb-1">
+                  <code className="font-mono font-bold text-gray-900">
+                    {entry.method}()
+                  </code>
+                  <div className="flex items-center space-x-2">
+                    <span
+                      className={`px-2 py-0.5 rounded font-semibold uppercase tracking-wider text-[10px] ${
+                        entry.status === 'synced'
+                          ? 'bg-green-100 text-green-800'
+                          : entry.status === 'error'
+                          ? 'bg-red-100 text-red-800'
+                          : 'bg-amber-100 text-amber-800'
+                      }`}
+                    >
+                      {entry.status === 'synced'
+                        ? 'Synced with Browser'
+                        : entry.status === 'error'
+                        ? 'Signal Error'
+                        : 'Signal Dispatched'}
+                    </span>
+                    <span className="text-gray-400">{entry.timestamp}</span>
+                  </div>
+                </div>
+                <p className="text-gray-700 mb-1.5">{entry.summary}</p>
+                <pre className="bg-gray-50 border border-gray-100 rounded p-2 text-[11px] font-mono text-gray-600 overflow-x-auto">
+                  {JSON.stringify(entry.payload, null, 2)}
+                </pre>
+              </li>
+            ))}
+          </ul>
+        )}
+      </section>
+    </div>
+  );
+}
