+import type { APIRoute } from 'astro';
+import { generateAuthenticationOptions } from '@simplewebauthn/server';
+import { RP_ID } from '../../../../utils/auth-db';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    let body: { immediate?: boolean } = {};
+    try {
+      body = await request.json();
+    } catch {
+      body = {};
+    }
+
+    const options = await generateAuthenticationOptions({
+      rpID: RP_ID,
+      allowCredentials: body.immediate ? undefined : [],
+      userVerification: 'preferred',
+    });
+
+    options.rpId = RP_ID;
+
+    await session?.set('challenge', options.challenge);
+    await session?.set('expectedUserVerification', 'preferred');
+
+    return new Response(JSON.stringify(options), {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    });
+  } catch (err) {
+    return new Response(
+      JSON.stringify({ error: 'Failed to generate authentication options.' }),
+      { status: 500, headers: { 'Content-Type': 'application/json' } }
+    );
+  }
+};
