+      }
+      return '';
+    }
+
+    async function fetchWithPolicyHandling(url, { statusElement = statusBox, ...fetchOptions } = {}) {
+      try {
+        const response = await fetch(url, fetchOptions);
+        const body = await response.text();
+        let data = null;
+        try {
+          data = body ? JSON.parse(body) : null;
+        } catch {
+          data = null;
+        }
