+        if (statusElement) {
+          statusElement.dataset.state = 'success';
+          statusElement.textContent =
+            (data && typeof data.message === 'string' && data.message) ||
+            `Thanks for subscribing! Your signup request was sent (${body.length} bytes).`;
+        }
+        return { ok: true, body, data, error: null };
+      } catch (error) {
+        const message = error instanceof Error ? error.message : String(error);
+        if (statusElement) {
+          statusElement.dataset.state = 'error';
+          statusElement.textContent =
+            `Sorry, your request to ${url} could not go through. It may have been blocked by our outbound connection policy or failed due to a network error (${message}).`;
