+      if (errorMsg) {
+        emailInput.setCustomValidity(errorMsg);
+        emailInput.setAttribute('aria-invalid', 'true');
+        setStatusMessage(`Error: ${errorMsg}`, 'error');
+        emailInput.focus();
+        return;
+      }
+
+      emailInput.setCustomValidity('');
+      emailInput.removeAttribute('aria-invalid');
+      submitBtn.disabled = true;
+
+      try {
+        const endpoint = newsletterForm.getAttribute('action') || '/api/newsletter';
+        const result = await fetchWithPolicyHandling(endpoint, {
+          method: 'POST',
+          headers: {
+            'Content-Type': 'application/json',
+            Accept: 'application/json',
+          },
+          body: JSON.stringify({ email: emailInput.value.trim() }),
+          statusElement: statusBox,
+        });
+
+        if (result.ok) {
+          newsletterForm.reset();
+        }
+      } finally {
+        submitBtn.disabled = false;
+      }
+    });
+  </script>
+
