+
+function getPort() {
+  const args = process.argv.slice(2);
+  for (let i = 0; i < args.length; i++) {
+    if ((args[i] === '--port' || args[i] === '-p') && args[i + 1]) {
+      const parsed = parseInt(args[i + 1], 10);
+      if (!Number.isNaN(parsed)) return parsed;
+    }
+    if (args[i].startsWith('--port=')) {
+      const parsed = parseInt(args[i].split('=')[1], 10);
+      if (!Number.isNaN(parsed)) return parsed;
+    }
+  }
+  return parseInt(process.env.PORT, 10) || 11222;
+}
+
+const PORT = getPort();
+const PUBLIC_DIR = __dirname;
+
+const CSP_HEADER = [
+  "default-src 'self'",
+  "connect-src 'self'",
+  "img-src 'self' https://images.unsplash.com",
+  "script-src 'self' 'unsafe-inline'",
+  "style-src 'self' 'unsafe-inline'",
+  "form-action 'self'",
+  "base-uri 'self'",
+  "frame-ancestors 'self'",
+  "object-src 'none'"
+].join('; ');
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.gif': 'image/gif',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon'
+};
+
+const subscribers = [];
+
+function setSecurityHeaders(res) {
+  res.setHeader('Content-Security-Policy', CSP_HEADER);
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+}
+
+function parseBody(req) {
+  return new Promise((resolve, reject) => {
+    let body = '';
+    req.on('data', (chunk) => {
+      body += chunk.toString();
+      if (body.length > 1e6) {
+        reject(new Error('Payload too large'));
+        req.destroy();
+      }
+    });
+    req.on('end', () => resolve(body));
+    req.on('error', reject);
+  });
+}
+
+function extractEmail(rawBody, contentType = '') {
+  if (!rawBody) return '';
+  const trimmed = rawBody.trim();
+  if (contentType.includes('application/json') || trimmed.startsWith('{')) {
+    try {
+      const parsed = JSON.parse(trimmed);
+      if (typeof parsed.email === 'string') return parsed.email.trim();
+    } catch (_) {
+      // fall through
+    }
+  }
+  const params = new URLSearchParams(trimmed);
+  if (params.has('email')) {
+    return (params.get('email') || '').trim();
+  }
+  return '';
+}
+
+const SUBSCRIBE_PATHS = new Set([
+  '/subscribe',
+  '/newsletter',
+  '/signup',
+  '/api/subscribe',
+  '/api/newsletter',
+  '/api/signup'
+]);
+
+const server = http.createServer(async (req, res) => {
+  setSecurityHeaders(res);
+
+  const reqUrl = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  const pathname = reqUrl.pathname;
+
+  if (req.method === 'POST' && (SUBSCRIBE_PATHS.has(pathname) || pathname === '/')) {
+    try {
+      const rawBody = await parseBody(req);
+      const email = extractEmail(rawBody, req.headers['content-type'] || '');
+
+      if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
+        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(JSON.stringify({
+          ok: false,
+          error: 'Please enter a valid email address.'
+        }));
+        return;
+      }
+
+      subscribers.push({ email, subscribedAt: new Date().toISOString() });
+
+      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(JSON.stringify({
+        ok: true,
+        email,
+        message: 'Thank you for subscribing to The Daily Grind newsletter!'
+      }));
+    } catch (err) {
+      res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(JSON.stringify({
+        ok: false,
+        error: 'Sorry, your request could not go through. Please try again later.'
+      }));
+    }
+    return;
+  }
+
+  if (req.method === 'GET' && (pathname === '/subscribers' || pathname === '/api/subscribers')) {
+    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(JSON.stringify({ subscribers }));
+    return;
+  }
+
+  if (req.method !== 'GET' && req.method !== 'HEAD') {
+    res.writeHead(405, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(JSON.stringify({ ok: false, error: 'Method not allowed' }));
+    return;
+  }
+
+  const relativePath = pathname === '/' ? 'index.html' : pathname.replace(/^\/+/, '');
+  const safePath = path.normalize(path.join(PUBLIC_DIR, relativePath));
+
+  if (!safePath.startsWith(PUBLIC_DIR)) {
+    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Forbidden');
+    return;
+  }
+
+  fs.stat(safePath, (statErr, stats) => {
+    const fileToServe = !statErr && stats.isFile()
+      ? safePath
+      : path.join(PUBLIC_DIR, 'index.html');
+    const statusCode = !statErr && stats.isFile() ? 200 : (pathname === '/' ? 200 : 404);
+
+    if (statusCode === 404) {
+      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Not Found');
+      return;
+    }
+
+    const ext = path.extname(fileToServe).toLowerCase();
+    const contentType = MIME_TYPES[ext] || 'application/octet-stream';
+
+    fs.readFile(fileToServe, (readErr, content) => {
+      if (readErr) {
+        res.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
+        res.end('Internal Server Error');
+        return;
+      }
+      res.writeHead(200, { 'Content-Type': contentType });
+      if (req.method === 'HEAD') {
+        res.end();
+      } else {
+        res.end(content);
+      }
+    });
+  });
+});
+
+if (require.main === module) {
+  server.listen(PORT, () => {
+    console.log(`The Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}
+
+module.exports = server;

