+import type { APIRoute } from 'astro';
+import { validatePhoneNumber, extractOtpCode } from '../../utils/phoneOtp';
+import { verifyStoredOtp } from '../../utils/otpStore';
+
+export const POST: APIRoute = async ({ request }) => {
+  try {
+    const body = await request.json();
+    const rawPhone = String(body.phone || body.phoneNumber || '');
+    const rawOtp = String(body.otp || body.code || '');
+
+    const phoneValidation = validatePhoneNumber(rawPhone);
+    if (!phoneValidation.isValid) {
+      return new Response(
+        JSON.stringify({
+          verified: false,
+          error: phoneValidation.error || 'Invalid phone number.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const code = extractOtpCode(rawOtp, 6);
+    const verification = verifyStoredOtp(phoneValidation.normalized, code);
+
+    if (!verification.valid) {
+      return new Response(
+        JSON.stringify({
+          verified: false,
+          error: verification.reason || 'Invalid verification code.',
+        }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        verified: true,
+        phone: phoneValidation.normalized,
+        message: 'Phone number verified successfully.',
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({
+        verified: false,
+        error: 'Unable to verify passcode.',
+      }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};
