+export interface TranslatorFactory {
+  availability(options: TranslatorCreateCoreOptions): Promise<BuiltInAIAvailability>;
+  create(options: TranslatorCreateOptions): Promise<BuiltInTranslator>;
+}
+
+export interface LanguageDetectionResult {
+  detectedLanguage: string;
+  confidence: number;
+}
+
+export interface BuiltInLanguageDetector {
+  detect(input: string, options?: { signal?: AbortSignal }): Promise<LanguageDetectionResult[]>;
+  destroy?(): void;
+}
+
+export interface LanguageDetectorFactory {
+  availability(options?: { expectedInputLanguages?: string[] }): Promise<BuiltInAIAvailability>;
+  create(options?: {
