+            .trim()
+            .toLowerCase();
+          return (
+            msgType === 'init' ||
+            msgType === 'widget_init' ||
+            msgType === 'widget-init' ||
+            msgType === 'initialize' ||
+            msgType === 'register' ||
+            msgType === 'handshake' ||
+            data.init === true
