+            const invalidResult = {
+              accepted: false,
+              category: 'ordering',
+              reason: 'invalid-payload'
+            };
+            messageHistory.push({
+              origin: event.origin,
+              accepted: false,
+              category: 'ordering',
+              reason: invalidResult.reason
+            });
+            return invalidResult;
+          }
+
+          const summary = formatPayloadText(data);
+          updateOrderingUI(true, summary, event.origin);
+          const acceptedResult = {
+            accepted: true,
+            category: 'ordering',
+            reason: 'verified-trusted-ordering-origin',
+            origin: event.origin,
+            data: data
+          };
+          messageHistory.push({
+            origin: event.origin,
+            accepted: true,
+            category: 'ordering',
+            reason: acceptedResult.reason
+          });
